package com.gato.relay.definition

/**
 * Vanilla item palette (PMMP BedrockData required_item_list, ~1.26.2x):
 * gzip + base64 of the JSON map name -> {runtime_id, component_based}.
 * Embedded as a Kotlin constant — Java resources from local jar deps are not
 * reliably packaged into the APK on Android.
 */
object ItemPaletteData {

    private val CHUNKS = arrayOf(
        "",
        ""
    )

    fun decompressed(): String {
        val b64 = CHUNKS.joinToString("")
        val bytes = java.util.Base64.getDecoder().decode(b64)
        return String(java.util.zip.GZIPInputStream(bytes.inputStream()).readBytes(), Charsets.UTF_8)
    }
}
